const sample={title:'物体的沉与浮：用证据修正猜想',objectives:['能在实验前作出沉浮预测，记录观察并区分“猜想”和“证据”。','通过改变同一块橡皮泥的形状，观察其沉浮变化，认识到不能仅凭物体轻重判断沉浮。','能在小组讨论中用“我原来认为……观察到……现在认为……”说明观点变化。'],preparation:['每组一盆浅水、木块、石块和一块橡皮泥；备毛巾，铺防滑垫。','主备教师先试做橡皮泥小船，检查材料适用性；不能保证所有材料按预期沉浮。','无投影方案：黑板画“物体—预测—观察—新问题”四列表；每组在纸上记录。','用水前约定：不饮实验水，不向同学泼水，地面积水立即擦干。'],phases:[{name:'生活问题与预测',minutes:5,teacher:'展示木块和石块，问：“放进水里会怎样？你凭什么判断？”先收集不同想法，不立即公布结论。',student:'独立预测，再与同桌说出理由；允许用画图代替书写。',check:'请两名学生说出可检验的预测，区分“我猜”与“我看见”。'},{name:'分组观察与记录',minutes:8,teacher:'示范轻放物体，确认水深足够。分配操作员、记录员、观察员，提醒物体不触底、不受手托。',student:'依次放入木块、石块和实心橡皮泥，记录现象；发现与预测不同的结果时保留记录。',check:'巡视核对每组至少记录一种预测与观察的差异；材料结果不符预期时讨论原因。'},{name:'同一材料的形状挑战',minutes:12,teacher:'问：“不增减橡皮泥，怎样让它浮起来？”先让学生提出方案，再允许试做；提供捏成薄壁船形的分层提示。',student:'保持橡皮泥总量不变，改变形状并测试，记录成功与失败条件。',check:'要求学生说明保持了什么、改变了什么；不能仅凭一次失败断言“做不到”。'},{name:'交流证据与修正解释',minutes:8,teacher:'比较实心与船形橡皮泥的现象，追问：“重量近似不变，沉浮却可能改变，原先的解释还够用吗？”不把简单形状判断扩展为普遍定律。',student:'用观察证据解释观点变化，听取另一组的不同结果，提出进一步问题。',check:'能否指出“重的必沉、轻的必浮”不充分；教师核对表达，避免直接引入未经理解的公式。'},{name:'迁移与出口题',minutes:5,teacher:'给出两个问题：“大轮船很重，为什么不能只按重量判断？”“一次实验失败，下一步应检查什么？”',student:'独立作答，可口述或画图；同桌互相补充证据和限制条件。',check:'评价标准：指出轻重判断不足；提出检查进水、形状、水深或操作等合理因素。'},{name:'总结与材料整理',minutes:2,teacher:'请学生总结一个发现和一个未解决的问题，组织擦水、整理材料。',student:'完成一句话总结，确认桌面和地面无积水。',check:'收取出口题，课后据真实答题情况安排补学，不预填教学效果。'}],assessment:['过程评价：是否先预测再观察、是否完整记录、是否用证据修正观点。','出口题1：有人说“只要很重就会沉”，你会怎样回应？达标依据：指出不能只凭轻重，并引用本课实际观察。','出口题2：同样一块橡皮泥，两组结果不同，至少提出两项可检查条件。达标依据：能提出进水、形状、放置方式等具体条件。'],differentiation:['基础支持：提供图示记录表、句式支架，允许口述；教师协助操作，但保留学生预测机会。','进阶挑战：不增加橡皮泥总量，比较不同船形能承载的同类小物件数量；记录试验条件，避免宣称最优。','无投影、无网络：用实物演示与黑板表格替代幻灯片；材料不足时采取轮站观察。'],board:['左区：问题——只看轻重，能判断沉浮吗？','中区：物体｜预测｜观察｜新问题。','右区：同一块橡皮泥：总量不变，形状改变；用证据修正猜想。'],homework:['用画图或短文记录一个生活中的沉浮现象，写出一个希望进一步验证的问题。','不要求学生在无人看护时开展用水或户外实验。'],reflection:['哪些学生仍用“轻重”作唯一判断？依据哪一道实际回答？','材料、分组和用时是否合适？下一次保留或调整什么？','收集到哪些与预期不同的实验结果，应如何据此补充教学？'],sources:['应用内自编示例；使用前需教师对照当地教材版本、课程要求与真实学情核对。','实验必须课前试做；本示例不构成已实施教学或实测效果证明。']};
function validateClientLesson(p){if(!p||typeof p.title!=='string'||p.title.length>160)throw Error('教案标题无效');for(const k of ['objectives','preparation','assessment','differentiation','board','homework','reflection','sources'])if(!Array.isArray(p[k])||p[k].length>20||p[k].some(x=>typeof x!=='string'||x.length>1800))throw Error('教案字段无效：'+k);if(!Array.isArray(p.phases)||p.phases.length<2||p.phases.length>10)throw Error('课堂环节应为2至10个');let sum=0;for(const x of p.phases){if(!Number.isInteger(x.minutes)||x.minutes<1||x.minutes>120)throw Error('环节分钟数无效');sum+=x.minutes;for(const k of ['name','teacher','student','check'])if(typeof x[k]!=='string'||x[k].length>2000)throw Error('课堂环节内容无效')}if(sum>120)throw Error('总课时不能超过120分钟');return JSON.parse(JSON.stringify(p))}
