function getBrief(){const b={};for(const k of Object.keys(T().brief)){const el=$('brief-'+k);b[k]=el?el.value:T().brief[k]}b.minutes=Number(b.minutes);return b}
const briefFields=[['subject','学科','input'],['grade','年级','input'],['topic','课题','input'],['minutes','课时 / 分钟','number'],['learners','班级人数与分组','input'],['prior','学生已有知识','textarea'],['resources','可用设备与材料','textarea'],['context','教学场景','textarea'],['requirements','教学要求与修改意见','textarea']];
function prepForm(){const fields=briefFields.map(([k,title,type],i)=>'<div class="brief-field '+(k==='topic'?'wide':'')+'"><label class="field" for="brief-'+k+'">'+title+'</label>'+(type==='textarea'?'<textarea id="brief-'+k+'" rows="2">'+esc(T().brief[k])+'</textarea>':'<input class="input" id="brief-'+k+'" type="'+(type==='number'?'number':'text')+'" '+(type==='number'?'min="15" max="120" step="1"':'')+' value="'+esc(T().brief[k])+'">')+'</div>');return '<section class="panel prepform"><div class="form-title">'+uiIcon('edit')+'<h3>这节课的基本信息</h3></div><p class="hint">修改条件后，可以重新生成教案。</p><div class="brieffields"><div class="basic-fields">'+fields.slice(0,4).join('')+'</div><details class="extra-conditions"><summary>补充学情与教学条件 <small>选填</small></summary>'+fields.slice(4).join('')+'</details></div><div class="prepactions"><button class="btn primary" id="generateLesson" '+(generating?'disabled':'')+'>'+uiIcon('spark')+(generating?'正在生成，请稍候…':T().lesson?'按当前条件重新生成':'生成我的教案')+'</button><button class="btn small" id="loadLesson">载入示例体验</button></div><p class="hint">'+(ready?'AI 内容需教师核对。生成将使用上方条件与相关资料。':'当前未连接模型，可以先载入示例体验。')+'</p></section>'}

const sectionNames={objectives:'教学目标',preparation:'课前准备与安全',assessment:'学习评价',differentiation:'差异化支持与资源适配',board:'板书设计',homework:'课后任务',reflection:'课后反思',sources:'参考与核对事项'};
function lessonHtml(p){return '<div class="lessonpage"><div class="eyebrow">LESSON PLAN / 教学设计</div><h2>'+esc(p.title)+'</h2><div class="lessonmeta"><span class="pill">'+esc(T().brief.grade)+'</span><span class="pill">'+esc(T().brief.subject)+'</span><span class="pill">'+p.phases.reduce((a,x)=>a+x.minutes,0)+'分钟</span><span class="reviewbadge">待授课教师审阅</span></div>'+['objectives','preparation'].map(k=>listSection(k,p[k])).join('')+'<div class="lessonsection"><h3>课堂流程</h3>'+p.phases.map((x,i)=>'<div class="phase"><div class="phasehead"><span>'+String(i+1).padStart(2,'0')+' / '+esc(x.name)+'</span><span class="pill">'+x.minutes+'分钟</span></div><div class="phasebody"><div><small>教师行动</small><p>'+esc(x.teacher)+'</p></div><div><small>学生活动</small><p>'+esc(x.student)+'</p></div></div><div class="phasecheck"><strong>评价与反馈：</strong>'+esc(x.check)+'</div></div>').join('')+'</div>'+Object.keys(sectionNames).filter(k=>!['objectives','preparation'].includes(k)).map(k=>listSection(k,p[k])).join('')+'</div>'}
function listSection(k,items){return '<section class="lessonsection"><h3>'+sectionNames[k]+'</h3><ul>'+items.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></section>'}
function editorHtml(p){return '<section class="panel"><h3>编辑教案内容</h3><p class="hint">每行作为一个条目。保存会生成本地版本记录；未保存前切换标签会保留当前输入。</p><label class="field">教案标题</label><input class="input edit-title" id="editTitle" value="'+esc(p.title)+'">'+Object.keys(sectionNames).map(k=>'<label class="field">'+sectionNames[k]+'</label><textarea class="editfield" data-lesson-array="'+k+'" rows="3">'+esc((p[k]||[]).join('\n'))+'</textarea>').join('')+'<div class="sectionhead"><h3>课堂环节</h3><button class="btn small" id="addPhase">添加环节</button></div><div id="editPhases">'+p.phases.map((x,i)=>'<div class="phase" data-phase="'+i+'"><div class="two"><div><label class="field">名称</label><input class="input" data-phase-field="name" value="'+esc(x.name)+'"></div><div><label class="field">分钟数</label><input class="input" type="number" min="1" max="120" data-phase-field="minutes" value="'+x.minutes+'"></div></div>'+[['teacher','教师行动'],['student','学生活动'],['check','评价与反馈']].map(([k,t])=>'<label class="field">'+t+'</label><textarea class="editfield" data-phase-field="'+k+'">'+esc(x[k])+'</textarea>').join('')+'<button class="btn small" data-remove-phase="'+i+'" style="margin-top:12px">移除此环节</button></div>').join('')+'</div><button class="btn primary" id="saveLesson" style="margin-top:16px">保存修改与版本</button></section>'}
function readEditor(){if(!$('editTitle'))return T().lesson;const p={title:$('editTitle').value};document.querySelectorAll('[data-lesson-array]').forEach(el=>p[el.dataset.lessonArray]=el.value.split('\n').map(x=>x.trim()).filter(Boolean));p.phases=[...document.querySelectorAll('[data-phase]')].map(el=>{const o={};el.querySelectorAll('[data-phase-field]').forEach(f=>o[f.dataset.phaseField]=f.dataset.phaseField==='minutes'?Number(f.value):f.value);return o});return validateClientLesson(p)}
function splitLines(text,maxChars){const result=[];for(const paragraph of String(text).split('\n')){let chars=Array.from(paragraph);while(chars.length>maxChars){let cut=maxChars;for(let j=maxChars-1;j>=Math.floor(maxChars*.55);j--){if(/[。！？；，、]/.test(chars[j])){cut=j+1;break}}result.push(chars.splice(0,cut).join(''))}if(chars.length)result.push(chars.join(''))}return result}
function slideHeading(title,cover){const chars=Array.from(title),limit=cover?56:44;return chars.length>limit?chars.slice(0,limit).join('')+'…':title}

function makeSlides(p,template=false){const pages=[{title:template?'在这里填写课题':p.title,lines:template?['年级 · 学科 · 授课时长','一句话描述这节课的核心问题']:[T().brief.grade+' · '+T().brief.subject,p.phases.reduce((a,x)=>a+x.minutes,0)+'分钟 · 先提问，再用证据理解'],cover:true}];function add(title,lines){const chunks=lines.flatMap(x=>splitLines(x,96));let group=[],rows=0,part=0;for(const text of chunks){const need=Math.ceil(Array.from(text).length/28);if(rows+need>6&&group.length){pages.push({title:title+(part++?' · 续':''),lines:group});group=[];rows=0}group.push(text);rows+=need+0.7}if(group.length)pages.push({title:title+(part?' · 续':''),lines:group})}if(template){for(const [title,lines] of [['学习目标',['本节课结束时，学生能够……','请填写可观察、可检验的目标']],['情境导入',['展示一个生活问题或实物','先让学生表达预测与依据']],['探索活动',['材料：……','分组与角色：……','任务步骤：……']],['交流与解释',['学生观察到什么？','证据支持哪些结论？','还有哪些限制？']],['当堂评价',['出口题：……','判断依据：……']],['总结与迁移',['一个发现、一个理由、一个新问题','课后任务：……']]])add(title,lines);return pages}add('今天，我们要学会什么',p.objectives);for(const phase of p.phases){add(phase.name+' · '+phase.minutes+'分钟',['学习任务：'+phase.student,'想一想：'+phase.check])}add('带走一个发现',p.homework);return pages}
function slidesHtml(){const p=T().lesson,pages=makeSlides(p),i=Math.min(T().slideIndex||0,pages.length-1),s=pages[i],style=styles[T().style]||styles.forest;return '<div class="panel"><div class="previewaction"><div><h3>课堂课件预览</h3><span class="hint">'+pages.length+'页 · 16:9 · 文本与形状可编辑</span></div><select id="deckStyle" aria-label="课件主题" style="width:auto">'+Object.entries(styles).map(([k,v])=>'<option value="'+k+'" '+(T().style===k?'selected':'')+'>'+v.name+'</option>').join('')+'</select></div><div class="slidepreview '+(s.cover?'slidecover':'')+'" style="--deck-cover:#'+style.primary+';background:#'+(s.cover?style.primary:style.paper)+';color:#'+(s.cover?'FFFFFF':style.ink)+'"><small style="color:inherit">启知未来 / '+esc(T().brief.subject)+'课堂</small><h2 style="color:inherit">'+esc(slideHeading(s.title,s.cover))+'</h2><ul>'+s.lines.map(l=>'<li>'+esc(l)+'</li>').join('')+'</ul><span class="slidenumber">'+String(i+1).padStart(2,'0')+' / '+pages.length+'</span></div><div class="slidethumbs">'+pages.map((x,n)=>'<button data-slide="'+n+'" class="'+(n===i?'active':'')+'">'+String(n+1).padStart(2,'0')+'<br>'+esc(x.title.slice(0,25))+'</button>').join('')+'</div><div class="row" style="margin-top:16px"><button class="btn primary" id="downloadPpt">导出PPTX</button><button class="btn" id="downloadBlank">导出此主题空白模板</button></div><p class="hint">PPT按学生任务和课堂提问编排；完整教师指导语见教案。无投影环境可改用实物、板书与纸质任务卡。</p></div>'}
function qualityHtml(p){const sum=p.phases.reduce((n,x)=>n+x.minutes,0);return '<div class="panel"><h3>备课检查</h3><div class="timelines">'+p.phases.map(x=>'<span title="'+esc(x.name)+' '+x.minutes+'分钟" style="flex:'+x.minutes+'"></span>').join('')+'</div><div class="progresslabel">'+sum+' / '+T().brief.minutes+'分钟</div><div class="qualitylist">'+['课时分配：'+(sum===Number(T().brief.minutes)?'与设定一致':'与设定不一致，请调整'), '目标条目：'+p.objectives.length+'项（可测量性需教师核对）','形成性检查：'+p.phases.filter(x=>x.check.trim()).length+'/'+p.phases.length+'个环节已填写','差异化支持：'+p.differentiation.length+'项','来源信息：'+p.sources.length+'条（真实性需核对）'].map(x=>'<div>'+esc(x)+'</div>').join('')+'</div><div class="notice">这是结构检查，不是教学质量评分。知识准确性、学情适配和实际效果仍需教师审阅与试教。</div></div>'}
function prepPage(){const p=T().lesson;return '<div class="work-heading"><div><span class="eyebrow">YOUR LESSON STUDIO</span><h1>'+(generating?'正在为你准备这节课。':p?'把这节课，准备得更好。':'从课题开始，准备一节好课。')+'</h1><p>'+(generating?'请保持页面打开。完成后会自动显示教案，再继续编辑和导出。':p?'先核对教案，再选择课件主题。所有内容都可以继续修改。':'填写基本信息，点击生成；也可以先载入示例，看看最终效果。')+'</p></div><button class="btn" data-teachgo="home">＋ 备一节新课</button></div>'+stageBar()+'<div class="preplayout">'+prepForm()+'<div class="lesson-workspace"><div class="preptabs">'+[['preview','查看教案'],['edit','编辑内容'],['slides','制作 PPT'],['dialogue','问问 AI'],['quality','课前检查']].map(([k,v])=>'<button data-preptab="'+k+'" class="'+(prepTab===k?'active':'')+'">'+v+'</button>').join('')+'</div>'+(generating?'<div class="generation-banner" role="status"><span class="loading-ring"></span><div><strong>正在准备你的教案</strong><small>正在组织教学目标、课堂活动和评价，请稍候。</small></div></div>':'')+(p?'<div class="previewaction"><span class="versionnote">v'+T().version+' · '+esc(T().origin||'手工编辑')+'</span><div class="row"><button class="btn small" id="downloadDoc">下载 Word</button><button class="btn small" data-next-slides>制作 PPT →</button></div></div>':'')+(prepTab==='dialogue'?'<div class="dialogue-intro"><strong>和 AI 一起打磨这节课</strong><p>例如：“把第二个活动改成不需要投影的版本”。建议确认后，可到“编辑内容”中修改教案。</p></div><div class="teacherchat">'+chat()+'</div>':!p&&generating?'<section class="empty-studio"><div class="empty-icon">'+uiIcon('book')+'</div><h2>正在准备：'+esc(T().brief.topic)+'</h2><p>无需重复点击。教案生成后会自动显示在这里。<br>你可以接着核对内容、制作 PPT 和下载 Word。</p></section>':!p?'<section class="empty-studio"><div class="empty-icon">'+uiIcon('book')+'</div><span class="eyebrow">你的教案将在这里生成</span><h2>先告诉我，你想教什么？</h2><p>填写左侧课题和基本信息，再点击“生成我的教案”。<br>我们会准备教学目标、活动安排、板书和课后任务。</p><button class="btn" id="emptyExample">不知道从哪开始？看完整示例 →</button><div class="empty-deliverables"><span>'+uiIcon('check')+' 可编辑教案</span><span>'+uiIcon('check')+' 可下载 PPT</span><span>'+uiIcon('check')+' 可交接备课包</span></div></section>':prepTab==='preview'?lessonHtml(p)+'<div class="next-action"><div><strong>教案核对好了？接着准备课件。</strong><small>选择喜欢的主题，导出可编辑的 PPT。</small></div><button class="btn primary" data-next-slides>下一步：制作 PPT '+uiIcon('arrow')+'</button></div>':prepTab==='edit'?editorHtml(T().draft||p):prepTab==='slides'?slidesHtml():qualityHtml(p))+'</div></div>'}

function templatesPage(){return hero('TEACHING TEMPLATES','好内容，也需要清楚的表达。','三套可编辑课堂课件主题，共用结构化教案。支持下载PPTX模板与Word教案模板。')+'<div class="templategrid">'+Object.entries(styles).map(([k,v])=>'<section class="templatecard"><div class="swatch" style="background:#'+v.paper+';color:#'+v.primary+'"><small>CLASSROOM / 课堂模板</small><strong>'+v.name+'</strong><span>课题 · 探索 · 评价</span></div><h3>'+v.name+'</h3><p>'+v.description+'</p><div class="row" style="margin-top:auto"><button class="btn primary small" data-template="'+k+'">下载PPT模板</button><button class="btn small" data-style="'+k+'">应用到当前教案</button></div></section>').join('')+'</div><section class="panel" style="margin-top:24px"><h3>通用教案与支教课堂方案</h3><p>模板包含学情、目标、准备、教师与学生活动、课堂评价、差异化支持、板书、作业和反思。课堂方案会随教案一同导出。</p><div class="row"><button class="btn" id="blankDoc">下载Word教案模板</button><button class="btn" id="openPrep">进入备课工作台</button></div></section>'}
function teamPage(){return hero('CO-PLANNING','把不同的经验，备进同一节课。','分工、审阅与版本交接集中在一个备课包中。当前采用文件交接协作，不提供跨账号实时同步。','<button class="btn primary" id="exportTeam">导出协同备课包 ↓</button>')+'<div class="workspace"><div><section class="panel"><div class="sectionhead" style="margin-top:0"><h3>团队分工</h3><button class="btn small" id="addMember">添加分工</button></div>'+T().members.map((m,i)=>'<div class="revision"><div class="two"><div><label class="field">成员称呼</label><input class="input" data-member="'+i+'" data-member-field="name" value="'+esc(m.name)+'"></div><div><label class="field">职责</label><input class="input" data-member="'+i+'" data-member-field="role" value="'+esc(m.role)+'"></div></div><label class="field">当前任务</label><input class="input" data-member="'+i+'" data-member-field="task" value="'+esc(m.task)+'"><div class="row" style="justify-content:space-between;margin-top:14px"><label class="hint" style="display:flex;align-items:center;gap:6px"><input type="checkbox" data-member-done="'+i+'" '+(m.done?'checked':'')+'> 已完成</label><button class="btn small" data-member-remove="'+i+'">移除</button></div></div>').join('')+'</section><section class="panel" style="margin-top:22px"><h3>审阅意见</h3><label class="field">审阅人称呼</label><input class="input" id="reviewer" placeholder="例如：主备教师 / 支教队员"><label class="field">修改建议</label><textarea id="reviewText" rows="3" placeholder="指出具体课堂环节、原因和建议…"></textarea><button class="btn primary" id="addReview" style="margin-top:14px">保存审阅意见</button>'+T().comments.map((c,i)=>'<div class="revision"><strong>'+esc(c.name)+'</strong><span class="hint"> · v'+c.version+' · '+new Date(c.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+'</span><p class="commenttext">'+esc(c.text)+'</p><label class="hint" style="display:flex;align-items:center;gap:6px"><input type="checkbox" data-review-done="'+i+'" '+(c.done?'checked':'')+'> 已处理</label></div>').join('')+'</section></div><div><section class="panel"><h3>接收协同备课包</h3><p class="hint">导入队友发来的.qizhi.json文件，继续编辑同一节课。导入前会展示标题和版本，并备份当前教案。称呼是自填信息，不代表身份认证。</p><label class="btn" for="teamFile">选择备课包</label><input type="file" id="teamFile" accept=".json" hidden><div id="importPreview"></div></section><section class="panel" style="margin-top:22px"><h3>本地版本记录</h3>'+(T().revisions.length?T().revisions.map((r,i)=>'<div class="revision"><strong>v'+r.version+' · '+esc(r.label)+'</strong><p>'+esc(r.lesson.title)+'</p><div class="row" style="justify-content:space-between;margin-top:10px"><span class="hint">'+new Date(r.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+'</span><button class="btn small" data-restore="'+i+'">恢复此版</button></div></div>').join(''):'<div class="empty">载入、编辑或生成教案后，旧版会保存在这里。</div>')+'</section></div></div>'}
function settingsPage(){return hero('CONNECTION STATUS','接通服务，让备课走得更远。','这里如实展示模型、登录与协作能力的连接状态。')+'<div class="workspace"><section class="panel"><h3>AI 模型服务</h3><div style="margin:10px 0"><span class="pill">'+(ready?'已配置，调用状态待测试':'尚未配置')+'</span></div><p>备课对话与教案生成通过服务端调用模型。密钥不进入浏览器，不保存在教案或备课包内。</p><div class="notice">模型配置由服务端管理；请测试API额度与响应。ChatGPT订阅本身不能替代应用的API配置。</div><button class="btn primary" id="testModel" style="margin-top:14px">测试模型连接</button><div id="modelTestResult" class="output">连接配置不代表账户额度可用，请测试真实响应。</div><h3 style="margin-top:28px">当前可用</h3><p class="hint">示例教案、手工编辑、三套PPT主题、Word/PPTX导出、分工与审阅、备课包交接、原有学习工具。</p></section><section class="panel"><h3>网站登录与在线协作</h3><div class="entry"><strong>公开评审入口</strong><p>当前网站支持免登录访问，不需要使用开发者个人账号。正式提交时，免登录作品的账号密码栏填写方式仍需以组委会要求为准。</p><span class="pill">持链接可访问</span></div><div class="entry"><strong>微信登录</strong><p>尚未接通。需要微信开放平台应用和回调域配置；当前托管环境未提供替换认证方式的配置。</p><span class="reviewbadge">需外部服务与部署方案</span></div><div class="entry"><strong>手机号验证码登录</strong><p>尚未接通。需要短信认证服务、有效发送配置及身份校验后端。</p><span class="reviewbadge">需外部服务与部署方案</span></div><div class="entry"><strong>跨账号在线同步</strong><p>尚未启用。当前通过备课包交接；后续需用户体系和云端存储。</p></div><p class="hint">没有使用通用验证码、假二维码或前端本地标记模拟身份认证。</p></section></div>'}
function teacherHome(){const t=T(),b=t.startDraft||{topic:'',subject:'科学',grade:'小学五年级',minutes:40};return '<div class="studio-welcome"><div><span class="welcome-tag">'+uiIcon('spark')+' 青年教师 & 支教团队的 AI 备课助手</span><h1>下一节好课，<br><em>从一个想法开始。</em></h1><p>告诉我你要教什么。教案、课堂活动、PPT，一起准备好。</p></div><div class="welcome-note"><span>LESSON STUDIO</span><strong>把时间留给<br>真正的教学。</strong><small>你的灵感，我们一起完善</small></div></div><div class="launch-grid"><section class="launch-panel"><div class="launch-heading"><span class="number-mark">01</span><div><h2>今天，准备教什么？</h2><p>填写课题即可开始，其余条件可以稍后调整。</p></div></div><form id="quickLesson"><label for="start-topic">课题 <span>必填</span></label><input id="start-topic" class="topic-input" required maxlength="160" placeholder="例如：物体的沉与浮、分数的初步认识…" value="'+esc(b.topic)+'"><div class="quick-options"><label>学科<input id="start-subject" required maxlength="40" value="'+esc(b.subject)+'"></label><label>年级<input id="start-grade" required maxlength="40" value="'+esc(b.grade)+'"></label><label>课时 / 分钟<input id="start-minutes" type="number" min="15" max="120" required value="'+esc(b.minutes)+'"></label></div><div class="launch-submit"><button class="btn primary" type="submit">'+uiIcon('spark')+' 开始生成教案 '+uiIcon('arrow')+'</button><span>生成后可编辑，再导出 Word / PPT</span></div></form><div class="try-example"><span>第一次使用？</span><button id="tryExample">先体验一份完整示例 '+uiIcon('arrow')+'</button><small>无需调用模型</small></div></section><aside class="outcome-panel"><span class="eyebrow">从想法，到课堂</span><h2>一次备课，<br>准备好整节课。</h2><div class="output-row"><span class="output-icon violet">'+uiIcon('book')+'</span><div><strong>一份完整教案</strong><small>教学目标 · 课堂流程 · 评价与作业</small></div><b>WORD</b></div><div class="output-row"><span class="output-icon peach">'+uiIcon('slides')+'</span><div><strong>一套课堂课件</strong><small>三种主题 · 可编辑 PPTX</small></div><b>PPT</b></div><div class="output-row"><span class="output-icon mint">'+uiIcon('team')+'</span><div><strong>一份协作备课包</strong><small>分工 · 审阅意见 · 文件交接</small></div><b>TEAM</b></div><div class="outcome-foot">'+uiIcon('check')+' 支持无投影、少器材等支教场景</div></aside></div><div class="how-it-works"><div><b>01</b><span><strong>告诉我课题</strong><small>选择年级、学科和课时</small></span></div><span class="step-arrow">→</span><div><b>02</b><span><strong>一起打磨教案</strong><small>编辑内容，或向 AI 提问</small></span></div><span class="step-arrow">→</span><div><b>03</b><span><strong>带着课件去上课</strong><small>选主题，下载 Word 和 PPT</small></span></div></div>'+(t.lesson?'<section class="resume-panel"><span class="output-icon violet">'+uiIcon('book')+'</span><div><small>继续上次的备课 · 当前浏览器</small><h3>'+esc(t.lesson.title)+'</h3><span>v'+t.version+' · 内容需授课教师审阅</span></div><button class="btn" data-teachgo="prep">继续编辑 '+uiIcon('arrow')+'</button></section>':'')+'<div class="shortcut-grid"><button data-teachgo="templates">'+uiIcon('slides')+'<span><strong>只想找个模板？</strong><small>下载教案和三套 PPT 模板</small></span>'+uiIcon('arrow')+'</button><button data-teachgo="team">'+uiIcon('team')+'<span><strong>和队友一起备课</strong><small>分配任务，审阅并交换备课包</small></span>'+uiIcon('arrow')+'</button></div>'}


nav=function(){originalNav();const c=$('navigation'),other=c.innerHTML.replace(/<button class="nav [^"]*" data-nav="home">[\s\S]*?<\/button>/,'');const menu=[['home','home','开始备课'],['prep','edit','我的教案与课件'],['templates','slides','模板中心'],['team','team','团队协作'],['settings','settings','模型与设置']];c.innerHTML='<div class="nav-caption">工作空间</div>'+menu.map(m=>'<button class="nav '+(active===m[0]?'active':'')+'" data-newnav="'+m[0]+'">'+uiIcon(m[1])+'<span>'+m[2]+'</span></button>').join('')+'<details class="nav-more" '+(modules.some(m=>m[0]===active)||['library','records'].includes(active)?'open':'')+'><summary>更多学习工具</summary>'+other+'</details><div class="nav-help"><span>'+uiIcon('spark')+'</span><strong>第一次来？从示例开始</strong><p>看看一份教案如何变成课堂课件。</p><button data-example-nav>体验完整示例 →</button></div>';c.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));c.querySelectorAll('[data-newnav]').forEach(b=>b.onclick=()=>{prepTab='preview';go(b.dataset.newnav)});c.querySelector('[data-example-nav]').onclick=()=>{go('prep');$('loadLesson').click()};const item=menu.find(m=>m[0]===active);if(item)$('crumb').textContent=item[2]};

