send=async function(){if(active==='prep'&&$('message')&&$('message').value.trim()&&T().lesson){const original=$('message').value;$('message').value=original+'\n\n当前备课条件：'+JSON.stringify(T().brief)+'\n当前教案：'+JSON.stringify(T().lesson).slice(0,6500)}return originalSend()};
