if(active==='team'){document.querySelectorAll('[data-member-field]').forEach(el=>el.oninput=()=>{T().members[Number(el.dataset.member)][el.dataset.memberField]=el.value.slice(0,300);saveTeaching()});document.querySelectorAll('[data-member-done]').forEach(el=>el.onchange=()=>{T().members[Number(el.dataset.memberDone)].done=el.checked;saveTeaching()});document.querySelectorAll('[data-member-remove]').forEach(el=>el.onclick=()=>{T().members.splice(Number(el.dataset.memberRemove),1);saveTeaching();render()});$('addMember').onclick=()=>{if(T().members.length>=20)return toast('最多20条分工');T().members.push({name:'',role:'',task:'',done:false});saveTeaching();render()};$('addReview').onclick=()=>{const name=$('reviewer').value.trim(),text=$('reviewText').value.trim();if(!name||!text)return toast('请填写审阅人称呼和意见');if(text.length>2000||name.length>100)return toast('审阅内容过长');T().comments.unshift({name,text,time:new Date().toISOString(),version:T().version,done:false});T().comments=T().comments.slice(0,100);saveTeaching();render()};document.querySelectorAll('[data-review-done]').forEach(el=>el.onchange=()=>{T().comments[Number(el.dataset.reviewDone)].done=el.checked;saveTeaching()});document.querySelectorAll('[data-restore]').forEach(el=>el.onclick=()=>{const old=T().revisions[Number(el.dataset.restore)];const snapshotCopy=JSON.parse(JSON.stringify(old));if(!confirm('恢复此教案版本？当前版本会先保存。'))return;snapshot('恢复前备份');T().lesson=snapshotCopy.lesson;T().brief=snapshotCopy.brief;T().draft=null;T().version++;T().origin='恢复自v'+snapshotCopy.version;saveTeaching();render()});$('exportTeam').onclick=()=>{if(!T().lesson)return toast('请先创建教案');const payload={format:'qizhi-teaching-v1',exportedAt:new Date().toISOString(),brief:T().brief,lesson:T().lesson,members:T().members,comments:T().comments,version:T().version,style:T().style};exportBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),safeName(T().lesson.title)+'_v'+T().version+'.qizhi.json');log('导出协同备课包',T().lesson.title)};$('teamFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>500000)throw Error('备课包不能超过500KB');const data=JSON.parse(await file.text());if(data.format!=='qizhi-teaching-v1')throw Error('不是有效的启知备课包');validateClientLesson(data.lesson);if(!data.brief||typeof data.brief.topic!=='string')throw Error('缺少有效备课条件');$('importPreview').innerHTML='<div class="notice">即将导入：'+esc(data.lesson.title)+'<br>文件版本：v'+esc(data.version)+'<br>当前教案会先保存为本地版本。导入会替换当前教案、分工和审阅意见，不自动合并。</div><button class="btn primary" id="confirmImport" style="margin-top:14px">确认导入</button>';$('confirmImport').onclick=()=>{snapshot('导入备课包前');T().lesson=validateClientLesson(data.lesson);T().brief=Object.fromEntries(Object.keys(T().brief).map(k=>[k,k==='minutes'?Number(data.brief[k])||40:String(data.brief[k]||'').slice(0,1800)]));T().members=Array.isArray(data.members)?data.members.slice(0,20).filter(m=>m&&typeof m==='object').map(m=>({name:String(m.name||'').slice(0,100),role:String(m.role||'').slice(0,100),task:String(m.task||'').slice(0,300),done:m.done===true})):[];T().comments=Array.isArray(data.comments)?data.comments.slice(0,100).filter(c=>c&&typeof c==='object').map(c=>({name:String(c.name||'').slice(0,100),text:String(c.text||'').slice(0,2000),time:Number.isNaN(Date.parse(c.time))?new Date().toISOString():c.time,version:Number.isSafeInteger(c.version)?c.version:0,done:c.done===true})):[];T().version=Math.max(T().version,Number.isSafeInteger(data.version)?data.version:0)+1;T().style=styles[data.style]?data.style:'forest';T().draft=null;T().origin='导入协同备课包 · 待审阅';saveTeaching();log('导入协同备课包',T().lesson.title);render();toast('已导入并备份当前版本')}}catch(e){toast(e.message)}}}
